  const WHEN: Record<Phase, string> = { now: T("Days 1–100", "الأيام 1–100"), next: T("Months 4–12", "الأشهر 4–12"), later: T("Years 2–3, after the gates", "السنتان 2–3 بعد البوابات"), hold: T("Sustain, no new step", "أبقِ، دون خطوة جديدة") };
