  const corr = d.axes.find((x) => x.id === "corridor"); const geo = d.pillars.find((p) => p.id === "geography"); const ex = hist.series.find((s) => s.id === "exports")?.last; const im = hist.series.find((s) => s.id === "imports")?.last; const sh = hist.series.find((s) => s.id === "share")?.last; const sc = d.deep?.screen;
